class RegulatoryCountryFilterPushdown extends Rule[LogicalPlan] {
  override def apply(plan: LogicalPlan): LogicalPlan = plan transform {
    case f @ Filter(_, _) if isRegulatoryTable(f.source) =>
      injectCountryIsolation(f)
  }
}

# Cluster registration:
spark.conf.set('spark.sql.extensions', 'com.gridunion.RegulatoryRuleExt')

# Behavior: fires automatically on every plan that touches regulatory tables.
# Other teams cannot opt out without changing cluster config.
